{
  "command": "git status --short && git log --oneline -8 && git diff --stat && git diff --name-only && find plans docs -type f | grep -Ei 'phase[- ]?0?5|adapter|ssh|port.forward' | head -100",
  "timeout": 120
}

{
  "command": "find . -maxdepth 3 -iname 'package.json' -o -iname 'pnpm-workspace.yaml'; printf '\\n--- TODO phase refs ---\\n'; rg -n -i 'phase.?0?5|TODO|FIXME' plans docs --glob '*.md' | head -200",
  "timeout": 120
}

{
  "command": "git diff -- apps/native/src/native-ssh-forward-host.ts apps/native/src/native-ssh-forward-host.test.ts packages/ui/src/lib/ssh-forward-host.ts packages/ui/src/lib/ssh-forward-host.test.ts packages/ui/src/contexts/SshForwardHostContext.tsx packages/ui/src/hooks/use-ssh-forward.ts apps/native/src/main.tsx packages/ui/src/api/server-config.ts packages/ui/src/hooks/use-server-profile.ts packages/ui/src/embed/dam-hopper-app.tsx && printf '\\n--- package scripts ---\\n' && node -e \"for(const f of ['package.json','apps/native/package.json','packages/ui/package.json']){let p=require('./'+f); console.log(f,p.scripts)}\"",
  "timeout": 120
}

