export function updateProfile(
  id: string,
  data: Partial<Omit<ServerProfile, "id" | "createdAt">>,
): boolean {
  const profiles = getProfiles();
  const idx = profiles.findIndex((p) => p.id === id);
  if (idx >= 0) {
    profiles[idx] = { ...profiles[idx], ...data };
    return saveProfiles(profiles);
  }
  return false;
}

