116	  private async command<T>(command: string, extra: Record<string, unknown>): Promise<T> {
117	    if (!this.context || !this.activationToken || !this.scopeId || !this.scopeGeneration) throw IPC_UNAVAILABLE;
118	    const context = this.context;
119	    const token = this.activationToken;
120	    const scopeId = this.scopeId;
121	    const scopeGeneration = this.scopeGeneration;
122	    try {
123	      const result = await this.invoke<T>(command, { input: { context, activationToken: token, scopeId, scopeGeneration, ...extra } });
124	      if (!this.validBoundResult(result, context, token, scopeId, scopeGeneration)) throw IPC_UNAVAILABLE;
125	      if (this.isSnapshot(result)) this.snapshotState = result;
126	      return result;
127	    } catch (error) {
128	      if (parseSshForwardError(error)?.code !== "MANAGER_SESSION_MISMATCH" || this.reopening) throw error;
129	      this.reopening = true;
130	      try {
131	        await this.openClient(this.knownScopes);
132	        if (!this.scopeId) throw IPC_UNAVAILABLE;
133	        await this.activateScope(this.scopeId);
134	        return await this.command(command, extra);
135	      } finally { this.reopening = false; }
136	    }
