138	  private validActivation(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string | null): value is ScopeActivation {
139	    if (!value || typeof value !== "object") return false;
140	    const result = value as ScopeActivation;
141	    return validContext(result.context) && sameContext(result.context, context) && result.activationToken === token && result.scopeId === scopeId && isCounter(result.scopeGeneration) && (result.snapshot === null || (scopeId !== null && this.validBoundResult(result.snapshot, context, token, scopeId, result.scopeGeneration)));
142	  }
143	  private validBoundResult(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string, scopeGeneration: WireCounter): boolean {
144	    if (!value || typeof value !== "object") return false;
145	    const result = value as Partial<SshForwardSnapshot & KeyInventory>;
146	    return validContext(result.context) && sameContext(result.context, context) && result.scopeId === scopeId && result.scopeGeneration === scopeGeneration && ("activationToken" in result ? result.activationToken === token : true);
147	  }
148	  private requireSnapshot(): SshForwardSnapshot { if (!this.snapshotState) throw IPC_UNAVAILABLE; return this.snapshotState; }
149	  private isSnapshot(value: unknown): value is SshForwardSnapshot { return Boolean(value && typeof value === "object" && "profilesRevision" in value && "trustRevision" in value); }
150	  private async invoke<T>(command: string, input: Record<string, unknown>): Promise<T> { try { return await invoke<T>(command, input); } catch (error) { throw parseSshForwardError(error) ?? IPC_UNAVAILABLE; } }
151	  private async installListener(): Promise<void> {
152	    if (!this.listening) this.listening = listen<SshForwardEventHint>("ssh-forward:changed", (event) => this.handleHint(event.payload)).then((unlisten) => { if (this.disposed) unlisten(); else this.unlisten = unlisten; });
153	    return this.listening;
154	  }
155	  private handleHint(hint: SshForwardEventHint): void {
156	    const context = this.context;
157	    const snapshot = this.snapshotState;
158	    if (!context || !snapshot || hint.desktopInstanceId !== context.desktopInstanceId || hint.managerSessionId !== context.managerSessionId || hint.clientEpoch !== context.clientEpoch || hint.activationToken !== this.activationToken || hint.scopeId !== this.scopeId) return;
159	    if (![hint.scopeGeneration, hint.profilesRevision, hint.trustRevision].every(isCounter)) return;
160	    const stale = wireCounterToBigInt(hint.scopeGeneration) < wireCounterToBigInt(snapshot.scopeGeneration) || wireCounterToBigInt(hint.profilesRevision) < wireCounterToBigInt(snapshot.profilesRevision) || wireCounterToBigInt(hint.trustRevision) < wireCounterToBigInt(snapshot.trustRevision);
161	    if (stale) return;
162	    for (const listener of this.listeners) listener({ type: "changed", hint });
163	    this.requestHintSnapshot();
164	  }
165	  private requestHintSnapshot(): void {
166	    if (this.snapshotInFlight) { this.snapshotTrailing = true; return; }
167	    this.snapshotInFlight = true;
168	    void this.snapshot().catch(() => {}).finally(() => { this.snapshotInFlight = false; if (this.snapshotTrailing) { this.snapshotTrailing = false; this.requestHintSnapshot(); } });
169	  }
